// Flattens all app registrations and enterprise apps, keeps only credentials
// that expire within the threshold (or expired recently) and groups them per app.
const cfg = $('Set Notification Configurations').first().json;
const DAY = 24 * 60 * 60 * 1000;
const now = Date.now();
const threshold = Number(cfg.thresholdDays);
const lookback = Number(cfg.expiredLookbackDays);

const pages = [
  ...$('Fetch App Registrations').all().map(i => ({ type: 'application', page: i.json })),
  ...$('Fetch Enterprise Apps').all().map(i => ({ type: 'servicePrincipal', page: i.json })),
];

const status = d => (d < 0 ? 'Expired' : d <= 7 ? 'Critical' : 'Warning');
const results = [];

for (const { type, page } of pages) {
  for (const obj of page.value || []) {
    let creds;
    if (type === 'application') {
      creds = [
        ...(obj.passwordCredentials || []).map(c => ({ ...c, kind: 'Client secret' })),
        ...(obj.keyCredentials || []).map(c => ({ ...c, kind: 'Certificate' })),
      ];
    } else {
      // Enterprise apps: only SAML signing certificates are relevant here
      creds = (obj.keyCredentials || [])
        .filter(c => c.usage === 'Sign')
        .map(c => ({ ...c, kind: 'SAML signing certificate' }));
    }
    if (!creds.length) continue;

    const withDays = creds.map(c => ({
      ...c,
      daysLeft: Math.ceil((new Date(c.endDateTime).getTime() - now) / DAY),
    }));

    const expiring = withDays
      .filter(c => c.daysLeft <= threshold && c.daysLeft >= -lookback)
      // Skip credentials that were already rotated (a newer one of the same kind exists)
      .filter(c => !cfg.hideRotated ||
        !withDays.some(o => o.kind === c.kind && o.keyId !== c.keyId && o.daysLeft > threshold));

    if (!expiring.length) continue;

    const portalUrl = type === 'application'
      ? `https://entra.microsoft.com/#view/Microsoft_AAD_RegisteredApps/ApplicationMenuBlade/~/Credentials/appId/${obj.appId}`
      : `https://entra.microsoft.com/#view/Microsoft_AAD_IAM/ManagedAppMenuBlade/~/SignOn/objectId/${obj.id}/appId/${obj.appId}`;

    results.push({
      objectType: type,
      objectId: obj.id,
      appId: obj.appId,
      displayName: obj.displayName,
      portalUrl,
      worstDaysLeft: Math.min(...expiring.map(c => c.daysLeft)),
      credentials: expiring
        .sort((a, b) => a.daysLeft - b.daysLeft)
        .map(c => ({
          kind: c.kind,
          name: c.displayName || '(no description)',
          keyId: String(c.keyId).slice(0, 8),
          endDate: String(c.endDateTime).slice(0, 10),
          daysLeft: c.daysLeft,
          status: status(c.daysLeft),
        })),
    });
  }
}

results.sort((a, b) => a.worstDaysLeft - b.worstDaysLeft);
return results.map(json => ({ json }));

// Adds the owners (with a mailbox) returned by Graph to each app item.
// If the owner lookup failed for an app, the app is kept with an empty owner list.
const apps = $('Filter Expiring Credentials').all();

return $input.all().map((item, i) => {
  const owners = (item.json.value || [])
    .map(o => ({ name: o.displayName, email: o.mail || o.userPrincipalName }))
    .filter(o => o.email && o.email.includes('@'));
  return { json: { ...apps[i].json, owners } };
});

// Builds one HTML summary mail for the IT/security team.
const cfg = $('Set Notification Configurations').first().json;
const apps = $input.all().map(i => i.json);

const esc = s => String(s ?? '').replace(/[&<>"']/g, ch =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const color = { Expired: '#b91c1c', Critical: '#c2410c', Warning: '#a16207' };
const td = 'padding:6px 10px;border-bottom:1px solid #e5e7eb;';

const rows = apps.flatMap(app => app.credentials.map(c => `
  <tr>
    <td style="${td}"><a href="${esc(app.portalUrl)}">${esc(app.displayName)}</a></td>
    <td style="${td}">${esc(c.kind)}</td>
    <td style="${td}">${esc(c.name)} <span style="color:#6b7280">(${esc(c.keyId)}…)</span></td>
    <td style="${td}">${esc(c.endDate)}</td>
    <td style="${td}color:${color[c.status]};font-weight:600">${c.status} (${c.daysLeft} d)</td>
    <td style="${td}">${esc(app.owners.map(o => o.name).join(', ') || '— no owner —')}</td>
  </tr>`)).join('');

const total = apps.reduce((n, a) => n + a.credentials.length, 0);
const expired = apps.reduce((n, a) => n + a.credentials.filter(c => c.status === 'Expired').length, 0);

const html = `
<div style="font-family:Segoe UI,Arial,sans-serif;font-size:14px;color:#111827">
  <p><b>${total - expired}</b> credential(s) expire within the next ${cfg.thresholdDays} days,
  <b style="color:${color.Expired}">${expired}</b> have already expired${Number(cfg.expiredLookbackDays) < 3650 ? ` (last ${cfg.expiredLookbackDays} days)` : ''}
  (${apps.length} app(s) affected).</p>
  <table style="border-collapse:collapse;font-size:13px">
    <tr style="background:#f3f4f6;text-align:left">
      <th style="${td}">App</th><th style="${td}">Type</th><th style="${td}">Credential</th>
      <th style="${td}">Expires</th><th style="${td}">Status</th><th style="${td}">Owners</th>
    </tr>${rows}
  </table>
  <p style="color:#6b7280;font-size:12px">Generated by n8n. Rotated credentials are ${cfg.hideRotated ? 'hidden' : 'shown'}.${cfg.showAttribution ? `<br>Template by <a href="https://www.xamplo.com" style="color:#6b7280">xamplo</a> – automation experts for ITSM/ESM integrations.` : ''}</p>
</div>`;

const to = String(cfg.adminRecipients).split(',').map(s => s.trim()).filter(Boolean).join(', ');

return [{
  json: {
    to,
    subject: `[Entra ID] App credentials: ${[total - expired && `${total - expired} expiring`, expired && `${expired} expired`].filter(Boolean).join(', ')}`,
    html,
  },
}];

// Builds one mail per app, addressed to the app owners.
const app = $json;
const cfg = $('Set Notification Configurations').first().json;

const esc = s => String(s ?? '').replace(/[&<>"']/g, ch =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));

const list = app.credentials.map(c =>
  `<li><b>${esc(c.kind)}</b> "${esc(c.name)}" – expires ${esc(c.endDate)} (${c.status}, ${c.daysLeft} days)</li>`).join('');

const html = `
<div style="font-family:Segoe UI,Arial,sans-serif;font-size:14px;color:#111827">
  <p>Hello,</p>
  <p>you are listed as owner of the Entra ID app <b>${esc(app.displayName)}</b>
  (App ID <code>${esc(app.appId)}</code>). The following credential(s) need to be renewed:</p>
  <ul>${list}</ul>
  <p>Please create a new credential, update every system that uses it and then delete the old one:<br>
  <a href="${esc(app.portalUrl)}">Open the app in the Entra admin center</a></p>
  <p style="color:#6b7280;font-size:12px">Automated notification sent by n8n.${cfg.showAttribution ? `<br>Template by <a href="https://www.xamplo.com" style="color:#6b7280">xamplo</a> – automation experts for ITSM/ESM integrations.` : ''}</p>
</div>`;

return {
  json: {
    to: app.owners.map(o => o.email).join(', '),
    subject: app.worstDaysLeft < 0
      ? `Action needed: credential for "${app.displayName}" has expired`
      : `Action needed: credential for "${app.displayName}" expires in ${app.worstDaysLeft} days`,
    html,
  },
};
